function hm702_admin_url(string $u): string {$u=trim($u);if($u===''||$u==='#'||$u==='@account')return $u?:'#';if(str_starts_with($u,'/'))return $u;if(preg_match('~^https?://~i',$u))return $u;return '#';}
function hm702_upload_image(string $field,int $tid): string {
    if(empty($_FILES[$field]['tmp_name'])||!is_uploaded_file($_FILES[$field]['tmp_name']))return '';
    if((int)($_FILES[$field]['size']??0)>4*1024*1024)throw new RuntimeException('Logo must be 4 MB or smaller.');
    $fi=new finfo(FILEINFO_MIME_TYPE);$mime=$fi->file($_FILES[$field]['tmp_name']);$ext=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'][$mime]??'';if($ext==='')throw new RuntimeException('Logo must be PNG, JPG or WebP.');
    $dir=dirname(__DIR__).'/uploads/header';if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir))throw new RuntimeException('Unable to create header upload directory.');
    $name='tenant-'.$tid.'-'.date('YmdHis').'-'.bin2hex(random_bytes(4)).'.'.$ext;$dest=$dir.'/'.$name;if(!move_uploaded_file($_FILES[$field]['tmp_name'],$dest))throw new RuntimeException('Unable to save uploaded logo.');
    return '/uploads/header/'.$name;
}
function hm705_upload_brand_asset(string $field,int $tid,bool $favicon=false): string {
    if(empty($_FILES[$field]['tmp_name'])||!is_uploaded_file($_FILES[$field]['tmp_name']))return '';
    if((int)($_FILES[$field]['size']??0)>4*1024*1024)throw new RuntimeException(($favicon?'Favicon':'Logo').' must be 4 MB or smaller.');
    $fi=new finfo(FILEINFO_MIME_TYPE);$mime=(string)$fi->file($_FILES[$field]['tmp_name']);
    $types=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'];
    if($favicon){$types['image/x-icon']='ico';$types['image/vnd.microsoft.icon']='ico';}
    $ext=$types[$mime]??'';if($ext==='')throw new RuntimeException($favicon?'Favicon must be PNG, JPG, WebP or ICO.':'Logo must be PNG, JPG or WebP.');
    $dir=dirname(__DIR__).'/uploads/header';if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir))throw new RuntimeException('Unable to create header upload directory.');
    $kind=$favicon?'favicon':'logo';$name='tenant-'.$tid.'-'.$kind.'-'.date('YmdHis').'-'.bin2hex(random_bytes(4)).'.'.$ext;$dest=$dir.'/'.$name;
    if(!move_uploaded_file($_FILES[$field]['tmp_name'],$dest))throw new RuntimeException('Unable to save uploaded brand asset.');
    return '/uploads/header/'.$name;
}
